・力は矢印で表す。矢印の長さが大きさ、矢の向きが力の向き、矢印の始点が作用点
・この3つを「力の三要素」という。どれか1つでも違えば別の力になる★
・単位はN（ニュートン）、kN（キロニュートン、1kN＝1000N）を使う
・建築で扱う力は主に鉛直下向き（重さ）と水平方向（地震・風）の2種類
