・降伏点：応力度がほとんど増えずにひずみだけが伸びる（降伏棚）★
・塑性域：力を除いても変形が残る（残留ひずみ）
・引張強さ（最大応力度）を過ぎるとくびれが生じ破断する
・伸び（破断時のひずみ）が大きい鋼材は靱性に富み、地震に強い★
・コンクリートには明確な降伏点がなく、圧縮強度の3分の1程度までが直線的

