・耐震構造：柱・梁・壁を強くして地震力に耐える。最も一般的★
・制振（制震）構造：ダンパーで地震のエネルギーを吸収し、揺れを小さくする★
・免震構造：建物と地面を絶縁し、地震力そのものを建物に伝えにくくする★
・耐震は「耐える」、制振は「揺れを抑える」、免震は「揺れを伝えない」★
・免震は建物の固有周期を長くすることで地震力を大幅に減らす技術
・制振は主に中高層建物の揺れ低減や、繰り返し地震への対策に有効
・二級では3つの違いと、免震の周期・変位の性質が問われる★
