・地盤の強さを表す代表的な指標がN値（標準貫入試験の打撃回数）★
・地盤が建物を支えられる力を地耐力（許容応力度、許容支持力）という★
・地耐力は「支持力」と「沈下」の両方から決まる。どちらか小さいほうが支配する★
