　支持杭で特に問題になる。杭に想定外の圧縮力が加わる★
・水平力に対しては、杭の曲げ耐力と地盤の水平抵抗で抵抗する
・液状化のおそれがある層では、杭の水平抵抗を見込まない★

━━━━━━━━━━━━━━━━━━━━━━
