━━━━━━━━━━━━━━━━━━━━━━
・かすがい：コの字形の金物。最も簡易。N値0以下の場合に用いる★
・かど金物（CP-T、CP-L）：柱と横架材の入隅に取り付けるL形の金物★
・山形プレート（VP）：柱と横架材にまたがって留める山形の板★
・羽子板ボルト：柱と横架材、または梁と梁を締め付けるボルト付き金物★
