・あおり止め金物（ひねり金物・くら金物）：垂木と軒桁の接合に用い、屋根の吹上げに抵抗する★
・大引・根太受け金物：床組の接合を簡略化する
・柱脚金物、梁受け金物（ハンガー金物）も多用される

━━━━━━━━━━━━━━━━━━━━━━
