・木材は乾燥していれば非常に長持ちするが、湿気があると腐朽菌が繁殖する★
・またシロアリ（白蟻）は木材を食害し、構造耐力を大きく低下させる★
・木造建築物の劣化のほとんどは、この2つが原因★
・腐朽もシロアリも「水分」が共通の条件。だから防湿・換気が根本対策★
・法令上も、土台・地面に近い部分の防腐防蟻措置が義務づけられている★
・薬剤処理だけに頼らず、設計と施工で水を寄せ付けないことが最重要
・二級では腐朽の条件、シロアリの種類、防腐防蟻の方法が問われる★
