━━━━━━━━━━━━━━━━━━━━━━
・設計上の対策（最も重要）★
　基礎の立上りを高くする（地上300mm以上）★
　床下換気を十分に確保する（換気口または基礎パッキン）★
　防湿コンクリート・防湿フィルムで地面からの湿気を遮断する★
　雨仕舞いをよくし、外壁内部に通気層を設ける★
　浴室・洗面所などの水回りは防水措置を徹底する
・材料上の対策★
　耐久性の高い樹種を使う（ひのき、ひば、けやき、くり、べいひば）★
　辺材より心材のほうが耐久性が高い★
　保存処理材（加圧注入処理）を用いる
・薬剤処理★
　地面から1m以内の柱・筋かい・土台に防腐防蟻処理を行う★
　土壌処理（建物の下の土に薬剤を散布）
　ベイト工法（毒餌により巣ごと駆除する）★

【図解】防腐防蟻の3つのアプローチ
　対策の種類｜具体的方法｜効果の持続
