        emoji: '🏢',
        body: `▼ゼロから：2つの材料の弱点を補い合う仕組み
・コンクリートは圧縮に強いが引張には極端に弱い（引張強度は圧縮強度の約10分の1）★
・鉄筋は引張に強いが、細長いため圧縮では座屈しやすく、また錆びやすい★
・そこで「圧縮はコンクリート、引張は鉄筋」と役割分担させたのが鉄筋コンクリート（RC）★
・両者が一体となって働くのは、次の3つの性質があるからである★
　付着：コンクリートと鉄筋が強く付着し、力を伝え合う
　熱膨張率がほぼ等しい：温度変化で剥離しない★
　アルカリ性の保護：コンクリートの強アルカリが鉄筋を錆から守る★
・この3条件が成り立つからこそRCが実用材料になっている
⚠ 例えの限界：中性化が進むとアルカリ性が失われ、鉄筋が錆びてRCは劣化する

━━━━━━━━━━━━━━━━━━━━━━
🔑 RC造が成立する3つの条件
━━━━━━━━━━━━━━━━━━━━━━
・熱膨張係数がほぼ等しい★
　鋼 約1.0×10のマイナス5乗 毎度、コンクリート 約1.0×10のマイナス5乗 毎度
　→ 温度変化があっても、両者の間にずれが生じにくい★
・付着力がある★
　異形鉄筋の節（リブ）により、機械的なかみ合いで力が伝わる
　丸鋼より異形鉄筋のほうが付着力が大きい★
・アルカリ性による防錆★
　硬化したコンクリートは pH12〜13 の強アルカリ性
　この環境では鉄筋の表面に不動態被膜ができ、錆びない★
　中性化（pH低下）や塩化物イオンでこの被膜が壊れると鉄筋が腐食する★

【図解】RC造が成立する3条件
　条件｜内容｜壊れると起こること
　熱膨張率が同じ｜温度変化でずれない★｜剥離・ひび割れ
　付着力｜異形鉄筋の節でかみ合う★｜鉄筋が抜けて機能しない
　アルカリ性｜pH12〜13で不動態被膜を形成★｜中性化により鉄筋腐食★
　⇒ この3つがそろってはじめて鉄筋とコンクリートが一体として働く
　⚠ 鉄筋が錆びると体積が2.5倍程度に膨張し、かぶりコンクリートを押し割る

━━━━━━━━━━━━━━━━━━━━━━
🔑 RC造の長所と短所
━━━━━━━━━━━━━━━━━━━━━━
・長所★
　耐火性が高い（コンクリートが不燃で鉄筋を熱から守る）★
　耐久性が高い（適切に設計施工すれば60年以上）★
　遮音性が高い（重量があるため）★
　自由な形状が作れる（型枠次第）
　剛性が高く、揺れが小さい
・短所★
　自重が大きい（比重約2.4）→ 地震力が大きくなる★
　工期が長い（型枠・配筋・打設・養生）★
　施工の品質が現場条件に左右されやすい★
　ひび割れが発生しやすい
　解体・改修が難しい

━━━━━━━━━━━━━━━━━━━━━━
🔑 曲げを受けるRC梁の挙動
━━━━━━━━━━━━━━━━━━━━━━
・梁に曲げが作用すると、圧縮側と引張側に分かれる★
・引張側のコンクリートは早期にひび割れ、以後は引張力を負担しない★
・そこで設計上「引張側のコンクリートの引張抵抗は無視する」★
・引張力はすべて引張鉄筋（主筋）が負担する★
・圧縮側はコンクリートが負担し、圧縮鉄筋を配置して補助する
・中立軸より上が圧縮、下が引張（単純梁の場合）
・釣合い鉄筋比：コンクリートの圧縮破壊と鉄筋の降伏が同時に起こる鉄筋比★
　実際の設計では、鉄筋が先に降伏する（釣合い鉄筋比以下）ようにする★
　→ 鉄筋降伏が先行すると、じわじわ変形して壊れる（延性破壊）★

【図解】RC梁の曲げに対する役割分担
　部位｜負担する力｜担当する材料
　圧縮側（上側）｜圧縮力★｜コンクリート（＋圧縮鉄筋）
　引張側（下側）｜引張力★｜引張鉄筋（主筋）のみ★
　中立軸付近｜せん断力｜あばら筋（スターラップ）とコンクリート
　⇒ 引張側コンクリートの抵抗は無視するのが設計の前提
　⚠ 鉄筋量が多すぎると、鉄筋が降伏する前にコンクリートが圧壊し脆性破壊になる

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・○「鉄筋とコンクリートの熱膨張係数はほぼ等しい」
・×「コンクリートの引張強度は圧縮強度と同程度」→ 約10分の1★
・○「コンクリートのアルカリ性により鉄筋が保護される」
・×「設計では引張側コンクリートの引張抵抗も考慮する」→ 無視する★
・○「異形鉄筋は丸鋼より付着力が大きい」
・×「鉄筋比を大きくするほど梁は粘り強くなる」→ 釣合い鉄筋比を超えると脆性的★
・○「RC造は自重が大きいため地震力も大きくなる」
・中性化が鉄筋位置まで進むと、鉄筋が腐食し耐力が低下する★

★ここだけ暗記
・圧縮はコンクリート、引張は鉄筋が負担
・成立3条件は 熱膨張率が同じ・付着力・アルカリ性による防錆
・引張側コンクリートの抵抗は無視する
・鉄筋降伏が先行する設計（釣合い鉄筋比以下）にする
・RCは耐火・耐久・遮音に優れるが自重が大きい`,
