　モルタルの充填不良★
・対策★
　アンカーボルトを十分な本数・径・定着長さとする
　降伏後の伸び能力を確保する（ねじ部が先に破断しないようにする）★
　ベースプレートを厚くする
　根巻きまたは埋込み形式を採用する
・設計上ピンとしたなら、実際にも回転できる納まりにする（整合性）★

