・柱と梁だけの長方形は平行四辺形につぶれるが、斜材を入れると三角形になり変形しない★
・ラーメン構造が「曲げ」で抵抗するのに対し、ブレース構造は「軸力」で抵抗する★
・ブレースは剛性が高く、変形を小さく抑えられる★
・一方で、変形能力（靱性）は低く、粘り強さに欠ける★
