　塗装が不要で、メンテナンスコストを削減できる★
　海岸付近（塩分の多い環境）では安定さびが形成されにくく不適★
・その他の対策★
　水が滞留しない形状とする（水抜き孔を設ける）★
　閉鎖断面として内部への水の侵入を防ぐ
　異種金属の接触を避ける（電食を防ぐ）★
　定期的な点検と塗替え

【図解】主な防錆方法の比較
